// === Tab: mySketch ===
let num = 500; // Number of particles
let particles = [];
let generations = 0;
let targets = [];
let mutationRate = 0.01;

function setup() {
  createCanvas(windowWidth, windowHeight);
  noStroke();

  targets = createSmileyFace(); // Generate the target smiley face points

  for (let i = 0; i < num; i++) {
    particles.push(new Particle(random(width), random(height)));
  }
}

function draw() {
  background(0, 10);
  for (let particle of particles) {
    particle.update();
    particle.display();
  }

  if (frameCount % 60 === 0) {
    evolveParticles();
    generations++;
    console.log('Generation:', generations);
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

class Particle {
  constructor(x, y) {
    this.pos = createVector(x, y);
    this.vel = p5.Vector.random2D();
    this.acc = createVector();
    this.fitness = 0;
  }

  update() {
    this.vel.add(this.acc);
    this.pos.add(this.vel);
    this.acc.mult(0);
    this.edges();
    this.calculateFitness();
  }

  applyForce(force) {
    this.acc.add(force);
  }

  calculateFitness() {
    let minDist = Infinity;
    for (let target of targets) {
      let d = dist(this.pos.x, this.pos.y, target.x, target.y);
      if (d < minDist) {
        minDist = d;
      }
    }
    this.fitness = 1 / (minDist + 1);
  }

  edges() {
    if (this.pos.x < 0) this.pos.x = width;
    if (this.pos.y < 0) this.pos.y = height;
    if (this.pos.x > width) this.pos.x = 0;
    if (this.pos.y > height) this.pos.y = 0;
  }

  display() {
    fill(255);
    ellipse(this.pos.x, this.pos.y, 4, 4);
  }

  reproduce(partner) {
    let child = new Particle(random(width), random(height));
    child.vel = p5.Vector.lerp(this.vel, partner.vel, 0.5);
    if (random(1) < mutationRate) {
      child.vel = p5.Vector.random2D();
    }
    return child;
  }
}

function createSmileyFace() {
  let x = width / 2;
  let y = height / 2;
  let face = [];

  // Face circle
  for (let angle = 0; angle < TWO_PI; angle += 0.1) {
    let xPos = x + cos(angle) * 100;
    let yPos = y + sin(angle) * 100;
    face.push(createVector(xPos, yPos));
  }

  // Eyes
  face.push(createVector(x - 40, y - 40));
  face.push(createVector(x + 40, y - 40));

  // Smile
  for (let angle = PI / 4; angle < (3 * PI) / 4; angle += 0.1) {
    var xPos = x + cos(angle) * 60;
    var yPos = y + sin(angle) * 60 + 20;
    face.push(createVector(xPos, yPos));
  }

  return face;
}

function evolveParticles() {
  let matingPool = [];
  let maxFitness = 0;

  for (let particle of particles) {
    if (particle.fitness > maxFitness) {
      maxFitness = particle.fitness;
    }
  }

  for (let particle of particles) {
    let n = particle.fitness / maxFitness * 100;
    for (let j = 0; j < n; j++) {
      matingPool.push(particle);
    }
  }

  if (matingPool.length === 0) {
    console.log('No suitable mating pool, skipping evolution.');
    return;
  }

  for (let i = 0; i < particles.length; i++) {
    let parentA = random(matingPool);
    let parentB = random(matingPool);
    var child = parentA.reproduce(parentB);
    particles[i] = child;
  }
}

